INSERT IGNORE INTO internship_skills(internship_id,skill_id,is_required) SELECT i.internship_id,s.skill_id,1 FROM internships i JOIN skills s ON (i.title='Software Engineering Intern' AND s.name IN('JavaScript','React','Git')) OR (i.title='Backend Engineering Intern' AND s.name IN('Node.js','MySQL','Data Structures')) OR (i.title='Cloud Platform Intern' AND s.name IN('Linux','Docker','AWS')) OR (i.title='Data Analyst Intern' AND s.name IN('Python','Pandas','Power BI')) OR (i.title='Embedded Systems Intern' AND s.name IN('C','Embedded C','Linux')) OR (i.title='Frontend Engineering Intern' AND s.name IN('JavaScript','React','Figma')) OR (i.title='Android Development Intern' AND s.name IN('Kotlin','Android','REST APIs')) OR (i.title='Machine Learning Intern' AND s.name IN('Python','Machine Learning','Algorithms')) OR (i.title='Cybersecurity Intern' AND s.name IN('Networking','Linux','Cybersecurity')) OR (i.title='Systems Engineering Intern' AND s.name IN('C','Linux','Networking'));
